    (
        tab_chat,
        tab_models,
        tab_edit,
        tab_skills,
        tab_prompts,
        tab_author,
        tab_tools,
        tab_logs,
        tab_history,
    ) = st.tabs(
        [
            "💬 Chat Interface",
            "🧠 Models",
            "📝 Editor",
            "🧩 Skills",
            "📜 Prompts",
            "✍️ Create & Edit",
            "🔧 Tools",
            "🗒️ Message Logs",
            "🕒 Manage Sessions",
